<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
const props=defineProps<{applicant:any}>();
const review=(document:any,status:string)=>{const note=status==='revision_required'?window.prompt('Catatan perbaikan yang wajib ditampilkan ke pendaftar:')||'':null;if(status==='revision_required'&&!note)return;router.patch(`/admin/applicants/${props.applicant.id}/documents/${document.id}`,{verification_status:status,review_note:note},{preserveScroll:true});};
</script>
<template><Head :title="applicant.registration_number"/><main class="min-h-screen bg-slate-100 p-5"><section class="mx-auto max-w-5xl space-y-5"><Link href="/admin/applicants" class="text-emerald-700">← Data pendaftar</Link><article class="rounded-2xl bg-white p-7 shadow-sm"><p class="font-semibold text-emerald-700">{{applicant.registration_number}}</p><h1 class="text-3xl font-bold text-emerald-950">{{applicant.full_name}}</h1><div class="mt-5 grid gap-3 md:grid-cols-2"><p><b>Email:</b> {{applicant.email}}</p><p><b>WhatsApp:</b> {{applicant.whatsapp_display}}</p><p><b>Lahir:</b> {{applicant.birth_place}}, {{applicant.birth_date}}</p><p><b>Pembayaran:</b> {{applicant.payment_status}}</p></div></article><article class="rounded-2xl bg-white p-7"><h2 class="text-xl font-bold">Dokumen</h2><div class="mt-3 divide-y"><div v-for="d in applicant.documents" :key="d.id" class="flex flex-col justify-between gap-3 py-3 md:flex-row md:items-center"><span>{{d.type}}</span><span class="flex flex-wrap items-center gap-2"><a :href="`/admin/documents/${d.id}/download`" class="rounded-lg border px-3 py-1 text-emerald-800">Unduh</a><button type="button" @click="review(d,'valid')" class="rounded-lg bg-emerald-700 px-3 py-1 text-white">Valid</button><button type="button" @click="review(d,'revision_required')" class="rounded-lg bg-amber-100 px-3 py-1 text-amber-900">Perbaikan</button><b>{{d.verification_status}}</b></span></div></div></article></section></main></template>
